export enum MealType {
  Breakfast = 'Breakfast',
  Lunch = 'Lunch',
  Snacks = 'Snacks',
  Dinner = 'Dinner'
}

export interface FoodItem {
  name: string;
  isVeg: boolean;
  containsEgg?: boolean;
}

export interface Meal {
  type: MealType;
  items: FoodItem[];
  startTime: string; // HH:MM 24h format
  endTime: string;   // HH:MM 24h format
}

export interface DayMenu {
  day: string; // Monday, Tuesday, etc.
  meals: {
    [key in MealType]: Meal;
  };
}

export interface WeekMenu {
  days: DayMenu[];
}

export interface Facility {
  id: string;
  name: string;
  icon: string;
  timings: string;
  imageUrl: string;
  color: string;
  startTime: string; // For status calculation
  endTime: string;   // For status calculation
}

