import React from 'react';
import { Facility } from '../types';

interface FacilityCardProps {
  facility: Facility;
  onClick: (f: Facility) => void;
  currentTime: Date;
}

export const FacilityCard: React.FC<FacilityCardProps> = ({ facility, onClick, currentTime }) => {
  const getMinutes = (timeStr: string) => {
    const [h, m] = timeStr.split(':').map(Number);
    return h * 60 + m;
  };

  const currentMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
  const start = getMinutes(facility.startTime);
  const end = getMinutes(facility.endTime);
  const isOpen = currentMinutes >= start && currentMinutes < end;

  return (
    <button
      onClick={() => onClick(facility)}
      className="flex-shrink-0 w-40 text-left bg-white rounded-2xl p-4 shadow-sm border border-gray-100 active:scale-95 transition-all relative overflow-hidden group"
    >
      <div className={`h-10 w-10 ${facility.color} rounded-xl flex items-center justify-center text-xl mb-3 shadow-inner group-hover:scale-110 transition-transform`}>
        {facility.icon}
      </div>

      <h4 className="font-bold text-gray-900 text-sm leading-tight mb-1">{facility.name}</h4>
      <p className="text-[10px] text-gray-500 font-medium leading-tight mb-3 line-clamp-1">{facility.timings}</p>

      <div className="flex items-center gap-1.5">
        <span className={`h-1.5 w-1.5 rounded-full ${isOpen ? 'bg-green-500 animate-pulse' : 'bg-gray-300'}`}></span>
        <span className={`text-[10px] font-bold uppercase tracking-wider ${isOpen ? 'text-green-600' : 'text-gray-400'}`}>
          {isOpen ? 'Open Now' : 'Closed'}
        </span>
      </div>

      <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4 text-gray-300">
          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM6.75 9.25a.75.75 0 000 1.5h4.59l-2.1 1.95a.75.75 0 001.02 1.1l3.5-3.25a.75.75 0 000-1.1l-3.5-3.25a.75.75 0 10-1.02 1.1l2.1 1.95H6.75z" clipRule="evenodd" />
        </svg>
      </div>
    </button>
  );
};

