import React from 'react';
import { Meal, FoodItem } from '../types';

interface MealCardProps {
  meal: Meal;
  title?: string;
  isHero?: boolean;
  isVegOnly: boolean;
}

const FoodItemRow: React.FC<{ item: FoodItem; isVegOnly: boolean }> = ({ item, isVegOnly }) => {
  // If Veg Only is on, hide anything that isn't explicitly veg (including eggs)
  if (isVegOnly && !item.isVeg) return null;

  const isEgg = item.containsEgg;
  const isVeg = item.isVeg;

  // Color logic: Veg = Green, Non-Veg = Red, Egg = Yellow/Amber
  let borderColor = 'border-green-600';
  let dotColor = 'bg-green-600';

  if (!isVeg) {
    if (isEgg) {
      borderColor = 'border-amber-500';
      dotColor = 'bg-amber-500';
    } else {
      borderColor = 'border-red-600';
      dotColor = 'bg-red-600';
    }
  }

  return (
    <div className="flex items-start gap-3 py-2.5 border-b border-dashed border-gray-100 last:border-0 group">
      <div className={`mt-1 relative flex-shrink-0 h-4 w-4 rounded-[2px] border-[1.5px] ${borderColor} flex items-center justify-center`}>
        <div className={`h-2 w-2 rounded-full ${dotColor}`}></div>
      </div>
      <span className="text-gray-700 group-hover:text-gray-900 transition-colors font-medium text-[15px] leading-snug">
        {item.name}
      </span>
    </div>
  );
};

export const MealCard: React.FC<MealCardProps> = ({ meal, title, isHero = false, isVegOnly }) => {
  const hasItems = meal.items.some(i => !isVegOnly || i.isVeg);

  return (
    <div className={`relative overflow-hidden transition-all duration-300 
      ${isHero 
        ? 'bg-white shadow-xl shadow-orange-500/10 rounded-3xl border border-orange-100 ring-1 ring-orange-50' 
        : 'bg-white shadow-sm hover:shadow-md rounded-2xl border border-gray-100'
      }`}
    >
      {isHero && (
        <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-orange-400 via-red-500 to-orange-400"></div>
      )}

      <div className="p-6">
        <div className="flex justify-between items-start mb-5">
          <div>
            <h3 className={`${isHero ? 'text-2xl text-gray-900' : 'text-lg text-gray-800'} font-bold tracking-tight mb-1`}>
              {title || meal.type}
            </h3>
            <div className="flex items-center gap-1.5 text-gray-500 font-medium bg-gray-50 px-2 py-0.5 rounded-md w-fit">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3.5 h-3.5 opacity-60">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm.75-13a.75.75 0 00-1.5 0v5c0 .414.336.75.75.75h4a.75.75 0 000-1.5h-3.25V5z" clipRule="evenodd" />
              </svg>
              <span className="text-xs uppercase tracking-wide">{meal.startTime} - {meal.endTime}</span>
            </div>
          </div>
          <div className={`h-12 w-12 rounded-2xl flex items-center justify-center shadow-inner ${isHero ? 'bg-orange-50 text-2xl' : 'bg-gray-50 text-xl'}`}>
             {meal.type === 'Breakfast' && '🍳'}
             {meal.type === 'Lunch' && '🍛'}
             {meal.type === 'Snacks' && '☕'}
             {meal.type === 'Dinner' && '🥘'}
          </div>
        </div>

        <div className="space-y-0.5">
          {hasItems ? (
            meal.items.map((item, idx) => (
              <FoodItemRow key={idx} item={item} isVegOnly={isVegOnly} />
            ))
          ) : (
            <div className="py-6 text-center bg-gray-50 rounded-lg border border-gray-100 border-dashed">
                <p className="text-gray-400 text-sm font-medium">No items match your filter.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Facility } from '../types';

interface FacilityCardProps {
  facility: Facility;
  onClick: (f: Facility) => void;
  currentTime: Date;
}

export const FacilityCard: React.FC<FacilityCardProps> = ({ facility, onClick, currentTime }) => {
  const getMinutes = (timeStr: string) => {
    const [h, m] = timeStr.split(':').map(Number);
    return h * 60 + m;
  };

  const currentMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
  const start = getMinutes(facility.startTime);
  const end = getMinutes(facility.endTime);
  const isOpen = currentMinutes >= start && currentMinutes < end;

  return (
    <button
      onClick={() => onClick(facility)}
      className="flex-shrink-0 w-40 text-left bg-white rounded-2xl p-4 shadow-sm border border-gray-100 active:scale-95 transition-all relative overflow-hidden group hover:border-orange-100 hover:shadow-md"
    >
      <div className={`h-10 w-10 ${facility.color} rounded-xl flex items-center justify-center text-xl mb-3 shadow-inner group-hover:scale-110 transition-transform duration-300`}>
        {facility.icon}
      </div>

      <h4 className="font-bold text-gray-900 text-sm leading-tight mb-1">{facility.name}</h4>
      <p className="text-[10px] text-gray-500 font-medium leading-tight mb-3 line-clamp-1">{facility.timings}</p>

      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
            <span className={`h-1.5 w-1.5 rounded-full ${isOpen ? 'bg-green-500 animate-pulse' : 'bg-gray-300'}`}></span>
            <span className={`text-[10px] font-bold uppercase tracking-wider ${isOpen ? 'text-green-600' : 'text-gray-400'}`}>
            {isOpen ? 'Open Now' : 'Closed'}
            </span>
        </div>

        <div className="opacity-0 group-hover:opacity-100 transition-opacity bg-gray-50 p-1 rounded-md">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3 h-3 text-gray-400">
                <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
            </svg>
        </div>
      </div>
    </button>
  );
};

