interface FacilityCardProps {
  facility: Facility;
  onClick: (f: Facility) => void;
  currentTime: Date;
}

export const FacilityCard: React.FC<FacilityCardProps> = ({ facility, onClick, currentTime }) => {
  const getMinutes = (timeStr: string) => {
    const [h, m] = timeStr.split(':').map(Number);
    return h * 60 + m;
  };

  const currentMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
  const currentDay = currentTime.getDay();

  // Determine which shifts are active right now
  const activeShifts = facility.shifts?.filter(shift => {
    const isCorrectDay = shift.activeDays.includes(currentDay);
    const start = getMinutes(shift.startTime);
    const end = getMinutes(shift.endTime);
    return isCorrectDay && currentMinutes >= start && currentMinutes < end;
  }) || [];

  // General Open/Closed logic for standard cards
  const start = getMinutes(facility.startTime);
  const end = getMinutes(facility.endTime);
  const isCorrectDay = facility.activeDays ? facility.activeDays.includes(currentDay) : true;
  const isGeneralOpen = isCorrectDay && currentMinutes >= start && currentMinutes < end;

  const isDoctor = facility.id === 'doctor';

  return (
    <button
      onClick={() => onClick(facility)}
      className={`flex-shrink-0 w-44 text-left bg-white rounded-2xl shadow-sm border border-gray-100 active:scale-95 transition-all relative overflow-hidden group hover:border-orange-100 hover:shadow-md flex flex-col`}
    >
      {isDoctor ? (
        <div className="h-24 w-full relative flex-shrink-0">
          <img 
            src={facility.imageUrl} 
            alt={facility.name}
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-blue-900/90 via-blue-900/20 to-transparent"></div>
          <div className="absolute bottom-2 left-3 right-3 flex items-center gap-2">
            <div className="bg-white/20 backdrop-blur-md rounded-lg p-1 text-white">
                <span className="text-base leading-none">{facility.icon}</span>
            </div>
            <h4 className="font-bold text-white text-[13px] leading-tight drop-shadow-sm">{facility.name}</h4>
          </div>
        </div>
      ) : (
        <div className="p-4 pb-0 flex-shrink-0">
          <div className={`h-10 w-10 ${facility.color} rounded-xl flex items-center justify-center text-xl mb-3 shadow-inner group-hover:scale-110 transition-transform duration-300`}>
            {facility.icon}
          </div>
          <h4 className="font-bold text-gray-900 text-sm leading-tight mb-1">{facility.name}</h4>
        </div>
      )}

      <div className="p-3 pt-2 flex-grow flex flex-col justify-between">
        <div className="mb-2">
            {!isDoctor && (
                <p className="text-[10px] text-gray-500 font-bold leading-tight uppercase tracking-tight mb-2">
                    {facility.timings}
                </p>
            )}

            {/* Dynamic Status Tags */}
            <div className="flex flex-wrap gap-1.5 min-h-[1.5rem]">
                {isDoctor ? (
                    activeShifts.length > 0 ? (
                        activeShifts.map((s, i) => (
                            <span key={i} className="px-2 py-0.5 bg-green-50 text-green-700 text-[9px] font-black uppercase rounded-md border border-green-100 animate-in fade-in slide-in-from-bottom-1 duration-300">
                                {s.name.split(' ')[0]} Available
                            </span>
                        ))
                    ) : (
                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest italic">
                            Tap to view schedule
                        </span>
                    )
                ) : (
                    <div className="flex items-center gap-1.5">
                        <span className={`h-1.5 w-1.5 rounded-full ${isGeneralOpen ? 'bg-green-500 animate-pulse' : 'bg-gray-300'}`}></span>
                        <span className={`text-[10px] font-bold uppercase tracking-wider ${isGeneralOpen ? 'text-green-600' : 'text-gray-400'}`}>
                            {isGeneralOpen ? 'Open Now' : 'Closed'}
                        </span>
                    </div>
                )}
            </div>
        </div>

        {isDoctor && (
            <div className="mt-auto border-t border-gray-50 pt-2 flex items-center justify-between">
                <span className="text-[9px] font-black text-blue-600 uppercase tracking-tighter">View Full Schedule</span>
                <div className="bg-blue-50 p-1 rounded-md">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-2.5 h-2.5 text-blue-500">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M8.25 4.5l7.5 7.5-7.5 7.5" />
                    </svg>
                </div>
            </div>
        )}
      </div>
    </button>
  );
};

