import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_MENU, DEFAULT_FACILITIES, PROJECTS } from './constants';
import { WeekMenu, Meal, Facility, Project } from './types';
import { MealCard } from './components/MealCard';
import { Gatekeeper } from './components/Gatekeeper';
import { FacilityCard } from './components/FacilityCard';
import { ImageModal } from './components/ImageModal';
import posthog from 'posthog-js';

const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function App() {
  // --- AUTHENTICATION STATE ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isAuthChecking, setIsAuthChecking] = useState(true);
  const [dismissedProjects, setDismissedProjects] = useState<string[]>([]);
  const [copyFeedback, setCopyFeedback] = useState<string | null>(null);

  useEffect(() => {
    const authLocal = localStorage.getItem('campusbite_auth');
    const authSession = sessionStorage.getItem('campusbite_auth');
    const savedDismissed = localStorage.getItem('campussync_dismissed_projects');

    if (authLocal === 'true' || authSession === 'true') {
      setIsAuthenticated(true);
    }
    if (savedDismissed) {
      setDismissedProjects(JSON.parse(savedDismissed));
    }
    setIsAuthChecking(false);
  }, []);

  const [menuData] = useState<WeekMenu>(DEFAULT_MENU);
  const [facilities] = useState<Facility[]>(DEFAULT_FACILITIES);
  const [selectedFacility, setSelectedFacility] = useState<Facility | null>(null);

  const [realTime, setRealTime] = useState<Date>(new Date());
  const currentTime = realTime;

  const [currentDayIndex, setCurrentDayIndex] = useState<number>(currentTime.getDay());
  const [isVegOnly, setIsVegOnly] = useState<boolean>(false);

  useEffect(() => {
    const timer = setInterval(() => setRealTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const mealStatus = useMemo(() => {
    const effectiveDayIndex = currentTime.getDay();
    if (currentDayIndex !== effectiveDayIndex) return null;

    const currentDayName = daysOfWeek[effectiveDayIndex];
    const dayData = menuData.days.find(d => d.day === currentDayName);
    if (!dayData) return null;

    const getMinutes = (timeStr: string) => {
      const [h, m] = timeStr.split(':').map(Number);
      return h * 60 + m;
    };

    const currentMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const meals: Meal[] = [
      dayData.meals.Breakfast,
      dayData.meals.Lunch,
      dayData.meals.Snacks,
      dayData.meals.Dinner
    ];

    let currentMeal: Meal | null = null;
    let nextMeal: Meal | null = null;
    let label = '';

    for (let i = 0; i < meals.length; i++) {
      const m = meals[i];
      const start = getMinutes(m.startTime);
      const end = getMinutes(m.endTime);

      if (currentMinutes >= start && currentMinutes < end) {
        currentMeal = m;
        label = `Happening Now: ${m.type}`;
        nextMeal = meals[i + 1] || null; 
        break;
      }

      if (currentMinutes < start) {
        nextMeal = m;
        label = `Coming Up: ${m.type}`;
        break;
      }
    }

    if (!currentMeal && !nextMeal) {
        const nextDayIndex = (effectiveDayIndex + 1) % 7;
        const nextDayName = daysOfWeek[nextDayIndex];
        const nextDayData = menuData.days.find(d => d.day === nextDayName);
        if (nextDayData) {
            nextMeal = nextDayData.meals.Breakfast;
            label = `Tomorrow Morning: Breakfast`;
        }
    }

    return { currentMeal, nextMeal, label };
  }, [menuData, currentDayIndex, currentTime]);

  const handleDismissProject = (id: string) => {
    const updated = [...dismissedProjects, id];
    setDismissedProjects(updated);
    localStorage.setItem('campussync_dismissed_projects', JSON.stringify(updated));
    posthog.capture('project_dismissed', { projectId: id });
  };

  const handleCopyPin = (pin: string, projectId: string) => {
    navigator.clipboard.writeText(pin);
    setCopyFeedback(projectId);
    setTimeout(() => setCopyFeedback(null), 2000);
    posthog.capture('project_pin_copied', { projectId });
  };

  const isViewingToday = currentDayIndex === currentTime.getDay();

  if (isAuthChecking) return null;

  if (!isAuthenticated) {
    return <Gatekeeper onAuthenticated={() => {
      setIsAuthenticated(true);
      posthog.capture('app_unlocked', { method: 'gatekeeper' });
    }} />;
  }

  const activeProjects = PROJECTS.filter(p => !dismissedProjects.includes(p.id));
  const footerProjects = PROJECTS.filter(p => dismissedProjects.includes(p.id));

  return (
    <div className="min-h-screen pb-32 max-w-md mx-auto bg-stone-50 shadow-2xl relative selection:bg-orange-100">
      <header className="sticky top-0 z-30 px-5 py-3 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] backdrop-blur-xl bg-white/85 border-b border-gray-100 transition-all duration-300">
        <div className="flex justify-between items-end">
          <div className="flex flex-col">
            <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">
              Campus<span className="text-orange-600">Sync</span>
            </h1>
            <div className="flex items-center gap-1.5 mt-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {daysOfWeek[currentDayIndex]}
              </span>
              {isViewingToday && (
                <span className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse shadow-sm shadow-orange-200"></span>
              )}
            </div>
          </div>

          <div className="flex bg-gray-100/80 p-1 rounded-lg border border-gray-100">
             <button
                onClick={() => setIsVegOnly(false)}
                className={`px-3 py-1 rounded-[6px] text-[10px] font-bold transition-all duration-200 ${!isVegOnly ? 'bg-white text-gray-900 shadow-sm ring-1 ring-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
             >
                ALL
             </button>
             <button
                onClick={() => setIsVegOnly(true)}
                className={`px-3 py-1 rounded-[6px] text-[10px] font-bold transition-all duration-200 flex items-center gap-1.5 ${isVegOnly ? 'bg-green-50 text-green-700 shadow-sm ring-1 ring-green-100' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <div className={`h-1.5 w-1.5 rounded-full ${isVegOnly ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                VEG
             </button>
          </div>
        </div>
      </header>

      <main className="p-5 space-y-8">
        {/* Dynamic Contextual View */}
        {mealStatus && (
          <div className="space-y-4 animate-fade-in">
            <div className="flex items-center gap-2 pl-1">
              <div className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse"></div>
              <h2 className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em]">{mealStatus.label}</h2>
            </div>

            {mealStatus.currentMeal && (
              <MealCard meal={mealStatus.currentMeal} isHero={true} isVegOnly={isVegOnly} />
            )}

            {mealStatus.nextMeal && (
               <>
                {!mealStatus.currentMeal && (
                  <MealCard meal={mealStatus.nextMeal} isHero={true} isVegOnly={isVegOnly} title={`Next up: ${mealStatus.nextMeal.type}`} />
                )}
                {mealStatus.currentMeal && (
                    <div className="mt-6 opacity-90 scale-[0.98] origin-top transition-transform">
                         <div className="flex items-center gap-2 mb-3 ml-1">
                            <div className="h-1.5 w-1.5 rounded-full bg-gray-300"></div>
                            <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">Coming Next</span>
                         </div>
                        <MealCard meal={mealStatus.nextMeal} isVegOnly={isVegOnly} />
                    </div>
                )}
               </>
            )}
          </div>
        )}

        {/* Campus Services Tray */}
        <div className="pt-2">
           <div className="flex items-center gap-3 mb-4">
             <span className="text-xl">🏛️</span>
             <h3 className="text-lg font-bold text-gray-800 tracking-tight">Campus Services</h3>
             <div className="h-px bg-gray-100 flex-grow"></div>
           </div>

           <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-5 px-5 pb-2">
              {facilities.map((f) => (
                <FacilityCard 
                  key={f.id} 
                  facility={f} 
                  currentTime={currentTime}
                  onClick={(fac) => {
                    setSelectedFacility(fac);
                    posthog.capture('facility_viewed', { facility: fac.name });
                  }} 
                />
              ))}
           </div>
        </div>

        {/* Digital Initiatives Section (Active) */}
        {activeProjects.length > 0 && (
          <div className="pt-2 animate-fade-in">
            <div className="flex items-center gap-3 mb-4">
              <span className="text-xl">✨</span>
              <h3 className="text-lg font-bold text-gray-800 tracking-tight">Digital Labs</h3>
              <div className="h-px bg-gray-100 flex-grow"></div>
            </div>

            <div className="space-y-4">
              {activeProjects.map((proj) => (
                <div key={proj.id} className={`relative overflow-hidden rounded-3xl bg-gradient-to-br ${proj.color} p-[1px] shadow-lg shadow-indigo-100`}>
                  <div className="absolute top-2 right-2 z-10">
                    <button 
                      onClick={() => handleDismissProject(proj.id)}
                      className="h-8 w-8 rounded-full bg-black/10 text-gray-500 hover:text-gray-900 flex items-center justify-center backdrop-blur-md hover:bg-black/20 transition-all active:scale-90"
                      title="Move to footer"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3.5 h-3.5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>

                  <div className="bg-white rounded-[23px] p-5 relative overflow-hidden">
                    <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${proj.color} opacity-5 blur-3xl -mr-16 -mt-16`}></div>

                    <div className="flex items-center gap-4 mb-4">
                       <div className={`h-12 w-12 rounded-2xl bg-gradient-to-br ${proj.color} flex items-center justify-center text-2xl shadow-md text-white`}>
                          {proj.icon}
                       </div>
                       <div>
                          <h4 className="text-base font-black text-gray-900 leading-tight">{proj.name}</h4>
                          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mt-0.5">By Kanishk Rao</p>
                       </div>
                    </div>

                    <p className="text-sm text-gray-600 font-medium leading-relaxed mb-5 pr-6">
                      {proj.description}
                    </p>

                    <div className="grid grid-cols-1 gap-3">
                        <div className="flex items-center gap-2 bg-slate-50 p-2 pl-3 rounded-xl border border-slate-100 group">
                           <div className="flex-grow">
                             <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Access Code</p>
                             <p className="text-xs font-black text-slate-700 tracking-[0.2em]">{proj.pin}</p>
                           </div>
                           <button 
                             onClick={() => handleCopyPin(proj.pin, proj.id)}
                             className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all duration-300 ${copyFeedback === proj.id ? 'bg-green-600 text-white' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}`}
                           >
                              {copyFeedback === proj.id ? 'COPIED!' : 'COPY'}
                           </button>
                        </div>

                        <a 
                          href={proj.url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          onClick={() => posthog.capture('project_clicked', { projectId: proj.id })}
                          className={`w-full py-3.5 rounded-xl bg-gradient-to-r ${proj.color} text-white font-black text-xs tracking-[0.1em] text-center shadow-lg active:scale-[0.98] transition-all flex items-center justify-center gap-2`}
                        >
                          TRY {proj.name.toUpperCase()}
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3 h-3">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
                          </svg>
                        </a>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Full Day List */}
        <div>
           <div className="flex items-center gap-3 mb-5">
             <span className="text-xl">📅</span>
             <h3 className="text-lg font-bold text-gray-800 tracking-tight">Full Menu</h3>
             <div className="h-px bg-gray-100 flex-grow"></div>
           </div>

           <div className="space-y-5">
              {menuData.days.find(d => d.day === daysOfWeek[currentDayIndex])?.meals && 
                 (Object.values(menuData.days.find(d => d.day === daysOfWeek[currentDayIndex])!.meals) as Meal[]).map((meal) => {
                    if (mealStatus?.currentMeal === meal || mealStatus?.nextMeal === meal) return null;
                    return <MealCard key={meal.type} meal={meal} isVegOnly={isVegOnly} />;
                 })
              }
           </div>
        </div>

        <footer className="text-center pt-12 pb-24 px-6 mt-12">
          {/* Dismissed Projects Hub */}
          {footerProjects.length > 0 && (
            <div className="mb-12 animate-fade-in">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Other Initiatives</p>
                <div className="flex flex-col gap-2">
                   {footerProjects.map(proj => (
                     <a 
                       key={proj.id}
                       href={proj.url}
                       target="_blank"
                       rel="noopener noreferrer"
                       className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-gray-100 text-left shadow-sm active:scale-95 transition-all group"
                     >
                        <div className={`h-8 w-8 rounded-lg bg-gradient-to-br ${proj.color} flex items-center justify-center text-sm text-white flex-shrink-0 shadow-sm`}>
                          {proj.icon}
                        </div>
                        <div className="flex-grow">
                           <p className="text-[11px] font-black text-gray-800 leading-none">{proj.name}</p>
                           <p className="text-[9px] font-bold text-gray-400 mt-1 uppercase tracking-tighter">Code: {proj.pin}</p>
                        </div>
                        <div className="text-gray-300 group-hover:text-orange-500 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3 h-3">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
                          </svg>
                        </div>
                     </a>
                   ))}
                </div>
            </div>
          )}

          <div className="max-w-xs mx-auto space-y-8">
            <div className="flex flex-col items-center gap-2 opacity-30 grayscale hover:grayscale-0 hover:opacity-100 transition-all duration-700">
                <h2 className="text-xs font-black tracking-tighter text-gray-900 leading-none">
                  Campus<span className="text-orange-600">Sync</span>
                </h2>
                <div className="h-[1px] w-6 bg-orange-600/30 rounded-full"></div>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] text-gray-400 font-medium leading-relaxed px-4">
                This is an independent project created for student convenience and is not an official university platform. Please verify timings at source.
              </p>

              <div className="space-y-2">
                  <div className="h-px bg-gradient-to-r from-transparent via-gray-200 to-transparent w-full"></div>
                  <div className="flex flex-col gap-1.5">
                    <p className="text-[10px] text-gray-400 font-medium">
                      Spotted an error? <a href="https://www.linkedin.com/in/kanishkrao/" target="_blank" rel="noopener noreferrer" className="text-orange-600 hover:text-orange-700 font-bold hover:underline transition-colors">Reach out here</a>
                    </p>
                    <p className="text-[10px] text-gray-400 font-medium">
                      Designed & Developed by <a href="https://www.linkedin.com/in/kanishkrao/" target="_blank" rel="noopener noreferrer" className="text-orange-600 hover:text-orange-700 font-bold hover:underline transition-colors">Kanishk Rao</a>
                    </p>
                  </div>
              </div>
            </div>
          </div>
        </footer>
      </main>

      {/* Modals & Overlays */}
      <ImageModal 
        facility={selectedFacility} 
        onClose={() => setSelectedFacility(null)} 
      />

      <div className="fixed bottom-6 left-0 right-0 z-40 flex justify-center px-4 pointer-events-none">
        <div className="flex gap-1.5 bg-white/90 backdrop-blur-xl p-2 rounded-2xl shadow-2xl border border-white/50 pointer-events-auto ring-1 ring-gray-900/5">
            {daysOfWeek.map((d, idx) => {
                const short = d.substring(0, 1);
                const isActive = idx === currentDayIndex;
                const isToday = idx === currentTime.getDay();

                return (
                    <button 
                        key={d}
                        onClick={() => setCurrentDayIndex(idx)}
                        className={`w-10 h-10 rounded-xl text-xs font-bold flex items-center justify-center transition-all duration-300 relative
                            ${isActive ? 'bg-gray-900 text-white shadow-lg scale-105' : 'bg-transparent text-gray-400 hover:bg-gray-100 hover:text-gray-600'}
                            ${!isActive && isToday ? 'text-orange-500 font-extrabold bg-orange-50' : ''}
                        `}
                    >
                        {short}
                        {!isActive && isToday && (
                            <span className="absolute bottom-1.5 left-1/2 -translate-x-1/2 h-1 w-1 rounded-full bg-orange-500"></span>
                        )}
                    </button>
                )
            })}
        </div>
      </div>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DEFAULT_MENU, DEFAULT_FACILITIES, PROJECTS } from './constants';
import { WeekMenu, Meal, Facility, Project } from './types';
import { MealCard } from './components/MealCard';
import { Gatekeeper } from './components/Gatekeeper';
import { FacilityCard } from './components/FacilityCard';
import { ImageModal } from './components/ImageModal';
import posthog from 'posthog-js';

const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function App() {
  // --- AUTHENTICATION STATE ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isAuthChecking, setIsAuthChecking] = useState(true);
  const [dismissedProjects, setDismissedProjects] = useState<string[]>([]);
  const [copyFeedback, setCopyFeedback] = useState<string | null>(null);

  useEffect(() => {
    // RESET FOR TESTING: Clear dismissed state so the card shows up fresh
    localStorage.removeItem('campussync_dismissed_projects');

    const authLocal = localStorage.getItem('campusbite_auth');
    const authSession = sessionStorage.getItem('campusbite_auth');
    const savedDismissed = localStorage.getItem('campussync_dismissed_projects');

    if (authLocal === 'true' || authSession === 'true') {
      setIsAuthenticated(true);
    }
    if (savedDismissed) {
      setDismissedProjects(JSON.parse(savedDismissed));
    } else {
      setDismissedProjects([]);
    }
    setIsAuthChecking(false);
  }, []);

  const [menuData] = useState<WeekMenu>(DEFAULT_MENU);
  const [facilities] = useState<Facility[]>(DEFAULT_FACILITIES);
  const [selectedFacility, setSelectedFacility] = useState<Facility | null>(null);

  const [realTime, setRealTime] = useState<Date>(new Date());
  const currentTime = realTime;

  const [currentDayIndex, setCurrentDayIndex] = useState<number>(currentTime.getDay());
  const [isVegOnly, setIsVegOnly] = useState<boolean>(false);

  useEffect(() => {
    const timer = setInterval(() => setRealTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const mealStatus = useMemo(() => {
    const effectiveDayIndex = currentTime.getDay();
    if (currentDayIndex !== effectiveDayIndex) return null;

    const currentDayName = daysOfWeek[effectiveDayIndex];
    const dayData = menuData.days.find(d => d.day === currentDayName);
    if (!dayData) return null;

    const getMinutes = (timeStr: string) => {
      const [h, m] = timeStr.split(':').map(Number);
      return h * 60 + m;
    };

    const currentMinutes = currentTime.getHours() * 60 + currentTime.getMinutes();
    const meals: Meal[] = [
      dayData.meals.Breakfast,
      dayData.meals.Lunch,
      dayData.meals.Snacks,
      dayData.meals.Dinner
    ];

    let currentMeal: Meal | null = null;
    let nextMeal: Meal | null = null;
    let label = '';

    for (let i = 0; i < meals.length; i++) {
      const m = meals[i];
      const start = getMinutes(m.startTime);
      const end = getMinutes(m.endTime);

      if (currentMinutes >= start && currentMinutes < end) {
        currentMeal = m;
        label = `Happening Now: ${m.type}`;
        nextMeal = meals[i + 1] || null; 
        break;
      }

      if (currentMinutes < start) {
        nextMeal = m;
        label = `Coming Up: ${m.type}`;
        break;
      }
    }

    if (!currentMeal && !nextMeal) {
        const nextDayIndex = (effectiveDayIndex + 1) % 7;
        const nextDayName = daysOfWeek[nextDayIndex];
        const nextDayData = menuData.days.find(d => d.day === nextDayName);
        if (nextDayData) {
            nextMeal = nextDayData.meals.Breakfast;
            label = `Tomorrow Morning: Breakfast`;
        }
    }

    return { currentMeal, nextMeal, label };
  }, [menuData, currentDayIndex, currentTime]);

  const handleDismissProject = (id: string) => {
    const updated = [...dismissedProjects, id];
    setDismissedProjects(updated);
    localStorage.setItem('campussync_dismissed_projects', JSON.stringify(updated));
    posthog.capture('project_dismissed', { projectId: id });
  };

  const handleCopyPin = (pin: string, projectId: string) => {
    navigator.clipboard.writeText(pin);
    setCopyFeedback(projectId);
    setTimeout(() => setCopyFeedback(null), 2000);
    posthog.capture('project_pin_copied', { projectId });
  };

  const isViewingToday = currentDayIndex === currentTime.getDay();

  if (isAuthChecking) return null;

  if (!isAuthenticated) {
    return <Gatekeeper onAuthenticated={() => {
      setIsAuthenticated(true);
      posthog.capture('app_unlocked', { method: 'gatekeeper' });
    }} />;
  }

  const activeProjects = PROJECTS.filter(p => !dismissedProjects.includes(p.id));
  const footerProjects = PROJECTS.filter(p => dismissedProjects.includes(p.id));

  return (
    <div className="min-h-screen pb-32 max-w-md mx-auto bg-stone-50 shadow-2xl relative selection:bg-orange-100">
      <header className="sticky top-0 z-30 px-5 py-3 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] backdrop-blur-xl bg-white/85 border-b border-gray-100 transition-all duration-300">
        <div className="flex justify-between items-end">
          <div className="flex flex-col">
            <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">
              Campus<span className="text-orange-600">Sync</span>
            </h1>
            <div className="flex items-center gap-1.5 mt-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {daysOfWeek[currentDayIndex]}
              </span>
              {isViewingToday && (
                <span className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse shadow-sm shadow-orange-200"></span>
              )}
            </div>
          </div>

          <div className="flex bg-gray-100/80 p-1 rounded-lg border border-gray-100">
             <button
                onClick={() => setIsVegOnly(false)}
                className={`px-3 py-1 rounded-[6px] text-[10px] font-bold transition-all duration-200 ${!isVegOnly ? 'bg-white text-gray-900 shadow-sm ring-1 ring-gray-100' : 'text-gray-400 hover:text-gray-600'}`}
             >
                ALL
             </button>
             <button
                onClick={() => setIsVegOnly(true)}
                className={`px-3 py-1 rounded-[6px] text-[10px] font-bold transition-all duration-200 flex items-center gap-1.5 ${isVegOnly ? 'bg-green-50 text-green-700 shadow-sm ring-1 ring-green-100' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <div className={`h-1.5 w-1.5 rounded-full ${isVegOnly ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                VEG
             </button>
          </div>
        </div>
      </header>

      <main className="p-5 space-y-8">
        {/* Dynamic Contextual View */}
        {mealStatus && (
          <div className="space-y-4 animate-fade-in">
            <div className="flex items-center gap-2 pl-1">
              <div className="h-1.5 w-1.5 rounded-full bg-orange-500 animate-pulse"></div>
              <h2 className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em]">{mealStatus.label}</h2>
            </div>

            {mealStatus.currentMeal && (
              <MealCard meal={mealStatus.currentMeal} isHero={true} isVegOnly={isVegOnly} />
            )}

            {mealStatus.nextMeal && (
               <>
                {!mealStatus.currentMeal && (
                  <MealCard meal={mealStatus.nextMeal} isHero={true} isVegOnly={isVegOnly} title={`Next up: ${mealStatus.nextMeal.type}`} />
                )}
                {mealStatus.currentMeal && (
                    <div className="mt-6 opacity-90 scale-[0.98] origin-top transition-transform">
                         <div className="flex items-center gap-2 mb-3 ml-1">
                            <div className="h-1.5 w-1.5 rounded-full bg-gray-300"></div>
                            <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">Coming Next</span>
                         </div>
                        <MealCard meal={mealStatus.nextMeal} isVegOnly={isVegOnly} />
                    </div>
                )}
               </>
            )}
          </div>
        )}

        {/* Campus Services Tray */}
        <div className="pt-2">
           <div className="flex items-center gap-3 mb-4">
             <span className="text-xl">🏛️</span>
             <h3 className="text-lg font-bold text-gray-800 tracking-tight">Campus Services</h3>
             <div className="h-px bg-gray-100 flex-grow"></div>
           </div>

           <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-5 px-5 pb-2">
              {facilities.map((f) => (
                <FacilityCard 
                  key={f.id} 
                  facility={f} 
                  currentTime={currentTime}
                  onClick={(fac) => {
                    setSelectedFacility(fac);
                    posthog.capture('facility_viewed', { facility: fac.name });
                  }} 
                />
              ))}
           </div>
        </div>

        {/* Digital Initiatives Section (Active) */}
        {activeProjects.length > 0 && (
          <div className="pt-2 animate-fade-in">
            <div className="flex items-center gap-3 mb-4">
              <span className="text-xl">✨</span>
              <h3 className="text-lg font-bold text-gray-800 tracking-tight">Digital Labs</h3>
              <div className="h-px bg-gray-100 flex-grow"></div>
            </div>

            <div className="space-y-4">
              {activeProjects.map((proj) => (
                <div key={proj.id} className={`relative overflow-hidden rounded-3xl bg-gradient-to-br ${proj.color} p-[1px] shadow-lg shadow-indigo-100`}>
                  <div className="absolute top-2 right-2 z-10">
                    <button 
                      onClick={() => handleDismissProject(proj.id)}
                      className="h-8 w-8 rounded-full bg-black/10 text-gray-500 hover:text-gray-900 flex items-center justify-center backdrop-blur-md hover:bg-black/20 transition-all active:scale-90"
                      title="Move to footer"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3.5 h-3.5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>

                  <div className="bg-white rounded-[23px] p-5 relative overflow-hidden">
                    <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${proj.color} opacity-5 blur-3xl -mr-16 -mt-16`}></div>

                    <div className="flex items-center gap-4 mb-4">
                       <div className={`h-12 w-12 rounded-2xl bg-gradient-to-br ${proj.color} flex items-center justify-center text-2xl shadow-md text-white`}>
                          {proj.icon}
                       </div>
                       <div>
                          <h4 className="text-base font-black text-gray-900 leading-tight">{proj.name}</h4>
                          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mt-0.5">By Kanishk Rao</p>
                       </div>
                    </div>

                    <p className="text-sm text-gray-600 font-medium leading-relaxed mb-5 pr-6">
                      {proj.description}
                    </p>

                    <div className="grid grid-cols-1 gap-3">
                        <div className="flex items-center gap-2 bg-slate-50 p-2 pl-3 rounded-xl border border-slate-100 group">
                           <div className="flex-grow">
                             <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Access Code</p>
                             <p className="text-xs font-black text-slate-700 tracking-[0.2em]">{proj.pin}</p>
                           </div>
                           <button 
                             onClick={() => handleCopyPin(proj.pin, proj.id)}
                             className={`px-3 py-1.5 rounded-lg text-[10px] font-black transition-all duration-300 ${copyFeedback === proj.id ? 'bg-green-600 text-white' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}`}
                           >
                              {copyFeedback === proj.id ? 'COPIED!' : 'COPY'}
                           </button>
                        </div>

                        <a 
                          href={proj.url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          onClick={() => posthog.capture('project_clicked', { projectId: proj.id })}
                          className={`w-full py-3.5 rounded-xl bg-gradient-to-r ${proj.color} text-white font-black text-xs tracking-[0.1em] text-center shadow-lg active:scale-[0.98] transition-all flex items-center justify-center gap-2`}
                        >
                          TRY {proj.name.toUpperCase()}
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3 h-3">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
                          </svg>
                        </a>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Full Day List */}
        <div>
           <div className="flex items-center gap-3 mb-5">
             <span className="text-xl">📅</span>
             <h3 className="text-lg font-bold text-gray-800 tracking-tight">Full Menu</h3>
             <div className="h-px bg-gray-100 flex-grow"></div>
           </div>

           <div className="space-y-5">
              {menuData.days.find(d => d.day === daysOfWeek[currentDayIndex])?.meals && 
                 (Object.values(menuData.days.find(d => d.day === daysOfWeek[currentDayIndex])!.meals) as Meal[]).map((meal) => {
                    if (mealStatus?.currentMeal === meal || mealStatus?.nextMeal === meal) return null;
                    return <MealCard key={meal.type} meal={meal} isVegOnly={isVegOnly} />;
                 })
              }
           </div>
        </div>

        <footer className="text-center pt-12 pb-24 px-6 mt-12">
          {/* Dismissed Projects Hub */}
          {footerProjects.length > 0 && (
            <div className="mb-12 animate-fade-in">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Other Initiatives</p>
                <div className="flex flex-col gap-2">
                   {footerProjects.map(proj => (
                     <a 
                       key={proj.id}
                       href={proj.url}
                       target="_blank"
                       rel="noopener noreferrer"
                       className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-gray-100 text-left shadow-sm active:scale-95 transition-all group"
                     >
                        <div className={`h-8 w-8 rounded-lg bg-gradient-to-br ${proj.color} flex items-center justify-center text-sm text-white flex-shrink-0 shadow-sm`}>
                          {proj.icon}
                        </div>
                        <div className="flex-grow">
                           <p className="text-[11px] font-black text-gray-800 leading-none">{proj.name}</p>
                           <p className="text-[9px] font-bold text-gray-400 mt-1 uppercase tracking-tighter">Code: {proj.pin}</p>
                        </div>
                        <div className="text-gray-300 group-hover:text-orange-500 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-3 h-3">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25" />
                          </svg>
                        </div>
                     </a>
                   ))}
                </div>
            </div>
          )}

          <div className="max-w-xs mx-auto space-y-8">
            <div className="flex flex-col items-center gap-2 opacity-30 grayscale hover:grayscale-0 hover:opacity-100 transition-all duration-700">
                <h2 className="text-xs font-black tracking-tighter text-gray-900 leading-none">
                  Campus<span className="text-orange-600">Sync</span>
                </h2>
                <div className="h-[1px] w-6 bg-orange-600/30 rounded-full"></div>
            </div>

            <div className="space-y-4">
              <p className="text-[10px] text-gray-400 font-medium leading-relaxed px-4">
                This is an independent project created for student convenience and is not an official university platform. Please verify timings at source.
              </p>

              <div className="space-y-2">
                  <div className="h-px bg-gradient-to-r from-transparent via-gray-200 to-transparent w-full"></div>
                  <div className="flex flex-col gap-1.5">
                    <p className="text-[10px] text-gray-400 font-medium">
                      Spotted an error? <a href="https://www.linkedin.com/in/kanishkrao/" target="_blank" rel="noopener noreferrer" className="text-orange-600 hover:text-orange-700 font-bold hover:underline transition-colors">Reach out here</a>
                    </p>
                    <p className="text-[10px] text-gray-400 font-medium">
                      Designed & Developed by <a href="https://www.linkedin.com/in/kanishkrao/" target="_blank" rel="noopener noreferrer" className="text-orange-600 hover:text-orange-700 font-bold hover:underline transition-colors">Kanishk Rao</a>
                    </p>
                  </div>
              </div>
            </div>
          </div>
        </footer>
      </main>

      {/* Modals & Overlays */}
      <ImageModal 
        facility={selectedFacility} 
        onClose={() => setSelectedFacility(null)} 
      />

      <div className="fixed bottom-6 left-0 right-0 z-40 flex justify-center px-4 pointer-events-none">
        <div className="flex gap-1.5 bg-white/90 backdrop-blur-xl p-2 rounded-2xl shadow-2xl border border-white/50 pointer-events-auto ring-1 ring-gray-900/5">
            {daysOfWeek.map((d, idx) => {
                const short = d.substring(0, 1);
                const isActive = idx === currentDayIndex;
                const isToday = idx === currentTime.getDay();

                return (
                    <button 
                        key={d}
                        onClick={() => setCurrentDayIndex(idx)}
                        className={`w-10 h-10 rounded-xl text-xs font-bold flex items-center justify-center transition-all duration-300 relative
                            ${isActive ? 'bg-gray-900 text-white shadow-lg scale-105' : 'bg-transparent text-gray-400 hover:bg-gray-100 hover:text-gray-600'}
                            ${!isActive && isToday ? 'text-orange-500 font-extrabold bg-orange-50' : ''}
                        `}
                    >
                        {short}
                        {!isActive && isToday && (
                            <span className="absolute bottom-1.5 left-1/2 -translate-x-1/2 h-1 w-1 rounded-full bg-orange-500"></span>
                        )}
                    </button>
                )
            })}
        </div>
      </div>
    </div>
  );
}

